1	package jobs
2	
3	import (
4		"context"
5		"time"
6	)
7	
8	// MaxFinishedRuns is how many settled runs the registry keeps. Runs live for
9	// the session (D8) — they are not written anywhere and do not survive a
10	// restart — but a session that scans all day would otherwise grow a list
11	// nobody scrolls to the end of.
12	//
13	// Twenty is the count at which the oldest entry has stopped being useful: the
14	// question a jobs view answers about a finished run is "did that one work?",
15	// and it is asked about the last few.
16	const MaxFinishedRuns = 20
17	
18	// Registry is the one place that knows what is running.
19	//
20	// It is **not safe for concurrent use, deliberately**. It is owned by the
21	// router and mutated from Update alone, which is where Rule 110 puts every
22	// write to application state; a mutex here would say a Cmd may touch it, and
23	// that is exactly the thing that must stay untrue. What a Cmd does is return a
24	// message, and Update turns that into a transition.
25	type Registry struct {
26		runs   []*Run
27		nextID JobID
28		// clock is time.Now in production and a fixed hand in tests, so a run's
29		// StartedAt is an assertion rather than a tolerance.
30		clock func() time.Time
31	}
32	
33	// New returns an empty registry.
34	func New() *Registry {
35		return &Registry{clock: time.Now}
36	}
37	
38	// SetClock replaces the registry's idea of now. It exists for tests.
39	func (r *Registry) SetClock(clock func() time.Time) { r.clock = clock }
40	
41	// Start admits a run, stamps it and returns its identifier.
42	//
43	// The run arrives with every item queued and is registered from Update, at the
44	// moment the commands are dispatched — never from inside one (D10). Every
45	// launch site knows its full list of targets at that point, which is what makes
46	// "8 waiting" sayable at all.
47	func (r *Registry) Start(run Run) JobID {
48		r.nextID++
49		run.ID = r.nextID
50		if run.StartedAt.IsZero() {
51			run.StartedAt = r.now()
52		}
53		if run.Finished() {
54			run.EndedAt = run.StartedAt
55		}
56		r.runs = append(r.runs, &run)
57		r.prune()
58		return run.ID
59	}
60	
61	// Advance moves one item of a run to a new state.
62	//
63	// A transition addressed to a run or a target the registry does not hold is
64	// reported rather than ignored: it means a launch site emitted a message for
65	// work it never registered, and the visible symptom would be a row that spins
66	// for the life of the view — the failure this package exists to remove.
67	func (r *Registry) Advance(id JobID, target string, state ItemState, detail string) bool {
68		return r.advance(id, target, state, detail, nil)
69	}
70	
71	// advance is Advance with the cancel function a starting transition carries.
72	//
73	// It arrives here and not through a call of its own because the two are one
74	// event: the context is created inside the Cmd, so the function reaches Update
75	// in the very message that says the item started. Two calls would leave a
76	// window where the item is running and cannot be stopped.
77	func (r *Registry) advance(id JobID, target string, state ItemState, detail string, cancel context.CancelFunc) bool {
78		run := r.run(id)
79		if run == nil {
80			return false
81		}
82		for i := range run.Items {
83			if run.Items[i].Target != target {
84				continue
85			}
86			run.Items[i].State = state
87			run.Items[i].Detail = detail
88			switch {
89			case state.Terminal():
90				run.Items[i].cancel = nil
91			case cancel != nil:
92				run.Items[i].cancel = cancel
93			}
94			r.settle(run)
95			return true
96		}
97		return false
98	}
99	
100	// Transition is what a progress message says about one target.
101	//
102	// It exists so the router can apply a message without knowing the vocabulary of
103	// the view that sent it. A sync that was refused because the tree is dirty is a
104	// skip with a reason; only the workspaces package knows that, and it says so by
105	// answering this — see Reporter.
106	type Transition struct {
107		Kind   Kind
108		Target string
109		State  ItemState
110		Detail string
111	
112		// Cancel stops the work this transition reports as started, and is nil for
113		// every other transition and for the kinds that cannot be cut (D7).
114		//
115		// It travels on the transition rather than through a call of its own
116		// because the two are one event: the context is created inside the Cmd, so
117		// the function reaches Update in the message that says the item started.
118		Cancel context.CancelFunc
119	
120		// Discover says the target has no row yet and belongs to the open run of
121		// this kind (D3). Only a kind whose targets arrive progressively sets it —
122		// the clone, whose walk is what finds them — and for every other kind it
123		// stays false because the full list was known at launch.
124		Discover bool
125	}
126	
127	// Reporter is implemented by a message that reports on registered work.
128	//
129	// The alternative was a switch in the router mapping every view's outcome
130	// vocabulary onto item states, which puts each view's semantics in a file that
131	// belongs to none of them, and grows by one branch per view.
132	type Reporter interface {
133		Transition() Transition
134	}
135	
136	// Sealer is implemented by the message that says a kind's open run has found
137	// everything it is going to (D3).
138	//
139	// It is a second interface rather than a field on Transition because sealing
140	// names no target: the message that carries it is the closed event channel, and
141	// there is nothing for it to be about.
142	type Sealer interface {
143		Seal() Kind
144	}
145	
146	// Apply routes a transition to the run it belongs to. It reports whether one
147	// was found, which is how the router knows there is something new to broadcast.
148	func (r *Registry) Apply(t Transition) bool {
149		if t.Discover {
150			return r.Discover(t.Kind, t.Target, t.State, t.Detail)
151		}
152		id, ok := r.FindItem(t.Kind, t.Target)
153		if !ok {
154			return false
155		}
156		return r.advance(id, t.Target, t.State, t.Detail, t.Cancel)
157	}
158	
159	// Discover adds a target to the open run of a kind (D3).
160	//
161	// A target already there is advanced instead of duplicated: the walk reports a
162	// group it could not list as a target of its own, and that path may also have
163	// been found as a repository. One row, whichever arrives first.
164	func (r *Registry) Discover(kind Kind, target string, state ItemState, detail string) bool {
165		run := r.openRun(kind)
166		if run == nil {
167			return false
168		}
169		for i := range run.Items {
170			if run.Items[i].Target == target {
171				run.Items[i].State = state
172				run.Items[i].Detail = detail
173				r.settle(run)
174				return true
175			}
176		}
177		run.Items = append(run.Items, Item{Target: target, State: state, Detail: detail})
178		r.settle(run)
179		return true
180	}
181	
182	// Seal says the open run of a kind has discovered everything it is going to.
183	//
184	// Until it is called the run is unsettled whatever its items say, which is the
185	// point: a walk that has found three repositories and cloned all three is not
186	// done. Sealing is what lets the run finish, stamp EndedAt and let the spinner
187	// chain die.
188	func (r *Registry) Seal(kind Kind) bool {
189		run := r.openRun(kind)
190		if run == nil {
191			return false
192		}
193		run.open = false
194		r.settle(run)
195		return true
196	}
