198	// CancelOpen stops the open run of a kind.
199	//
200	// It exists because a progressive run is the one case a view can name without
201	// a target: there is exactly one open run per kind at a time — the screen that
202	// owns it is exclusive while it goes — so "the clone I am looking at" resolves
203	// without the view holding a JobID, which is the thing D1 keeps out of views.
204	func (r *Registry) CancelOpen(kind Kind) bool {
205		run := r.openRun(kind)
206		if run == nil {
207			return false
208		}
209		return r.Cancel(run.ID)
210	}
