212	// openRun is the run of a kind that is still discovering, if there is one.
213	//
214	// At most one can exist: an open run belongs to a screen that owns the display
215	// while it goes, so a second could only be started by leaving that screen —
216	// which closes the first. The newest wins if that invariant is ever broken, so
217	// the answer is the run a user is looking at rather than one they have left.
218	func (r *Registry) openRun(kind Kind) *Run {
219		for i := len(r.runs) - 1; i >= 0; i-- {
220			if r.runs[i].Kind == kind && r.runs[i].open {
221				return r.runs[i]
222			}
223		}
224		return nil
225	}
226	
227	// FindItem names the run a transition belongs to.
228	//
229	// The launch sites do not carry a JobID in their messages, and deliberately:
230	// a view would have to hold one, which means holding registry state — the thing
231	// D1 keeps out of the views — and it would have to hold it before the registry
232	// had allocated it. The router looks the run up instead, from what the message
233	// already says: the kind is decided by which message arrived, and the target is
234	// in it.
235	//
236	// The oldest unsettled run wins. Two live runs of one kind cannot hold the same
237	// target — that is what the busy() guards prevent, and they are answered from
238	// this registry now, so the exclusion is enforced rather than hoped for.
239	func (r *Registry) FindItem(kind Kind, target string) (JobID, bool) {
240		for _, run := range r.runs {
241			if run.Kind != kind || run.Finished() {
242				continue
243			}
244			for i := range run.Items {
245				if run.Items[i].Target == target && !run.Items[i].State.Terminal() {
246					return run.ID, true
247				}
248			}
249		}
250		return 0, false
251	}
252	
253	// AttachRun stores the cancel function that stops the run's queue, as opposed
254	// to one item's work.
255	func (r *Registry) AttachRun(id JobID, cancel context.CancelFunc) {
256		if run := r.run(id); run != nil {
257			run.cancel = cancel
258		}
259	}
260	
261	// Cancel asks a run to stop.
262	//
263	// What that means differs by kind, and the difference is not cosmetic (D7):
264	// the queue always stops, so nothing further starts, but work already in flight
265	// is only interrupted where interrupting it leaves nothing behind. A `git
266	// clone` is never cut — a cancelled one leaves half a repository on disk — and
267	// a delete is not cancellable at all, which is a guard the view carries
268	// (Kind.Cancellable).
269	//
270	// Queued items are marked skipped straight away: they will not run, and leaving
271	// them queued would keep the run reading as running forever.
272	func (r *Registry) Cancel(id JobID) bool {
273		run := r.run(id)
274		if run == nil || run.Finished() {
275			return false
276		}
277	
278		run.cancelled = true
279		// A cancelled walk finds nothing more, so the run is sealed here: leaving
280		// it open would keep it unsettled for the life of the session, spinner
281		// chain and all, with nothing left that could ever close it.
282		run.open = false
283		if run.cancel != nil {
284			run.cancel()
285			run.cancel = nil
286		}
287	
288		for i := range run.Items {
289			switch run.Items[i].State {
290			case ItemQueued:
291				run.Items[i].State = ItemSkipped
292				run.Items[i].Detail = "cancelled"
293			case ItemRunning:
294				// Asked to stop, not declared stopped: the item reports its own
295				// outcome when it gets there. Claiming it settled here would race
296				// the message that says how it actually ended.
297				if run.Items[i].cancel != nil {
298					run.Items[i].cancel()
299					run.Items[i].cancel = nil
300				}
301			}
302		}
303	
304		r.settle(run)
305		return true
306	}
307	
308	// CancelItem stops one target of a run, leaving the rest going.
309	//
310	// It is the narrow half of D7: the run-level Cancel stops the queue whatever
311	// the kind, and this cuts a single piece of work — which is only offered where
312	// cutting leaves nothing behind. The caller decides that (Run.ItemStoppable);
313	// this refuses only what it cannot do.
314	//
315	// A queued target is skipped outright, because it will not run. A running one
316	// is *asked* to stop and left running: it reports its own outcome when it gets
317	// there, and claiming it settled here would race the message that says how it
318	// actually ended — the same reason Cancel gives.
319	func (r *Registry) CancelItem(id JobID, target string) bool {
320		run := r.run(id)
321		if run == nil || run.Finished() {
322			return false
323		}
324		for i := range run.Items {
325			if run.Items[i].Target != target || run.Items[i].State.Terminal() {
326				continue
327			}
328			if run.Items[i].State == ItemQueued {
329				run.Items[i].State = ItemSkipped
330				run.Items[i].Detail = "cancelled"
331			} else if run.Items[i].cancel != nil {
332				run.Items[i].cancel()
333				run.Items[i].cancel = nil
334			}
335			r.settle(run)
336			return true
337		}
338		return false
339	}
340	
341	// Snapshot returns a copy of every run, oldest first.
342	//
343	// It is what JobsChangedMsg carries, and copying is what makes the broadcast
344	// honest: a view holds data, not a window onto state someone else is writing.
345	// The cancel functions are cleared on the way out — a snapshot cannot stop a
346	// job, which has to go through Cancel on the registry the router owns.
347	func (r *Registry) Snapshot() []Run {
348		out := make([]Run, 0, len(r.runs))
349		for _, run := range r.runs {
350			copied := *run
351			copied.cancel = nil
352			copied.Items = make([]Item, len(run.Items))
353			copy(copied.Items, run.Items)
354			for i := range copied.Items {
355				copied.Items[i].cancel = nil
356			}
357			out = append(out, copied)
358		}
359		return out
360	}
361	
362	// Running counts the runs that have not settled. It is what decides whether the
363	// router keeps its spinner chain alive, and what the degraded footer line
364	// counts (D9).
365	func (r *Registry) Running() int {
366		n := 0
367		for _, run := range r.runs {
368			if !run.Finished() {
369				n++
370			}
371		}
372		return n
373	}
374	
375	// Len returns how many runs the registry holds, settled ones included.
376	func (r *Registry) Len() int { return len(r.runs) }
377	
378	// run finds a run by identifier.
379	func (r *Registry) run(id JobID) *Run {
380		for _, run := range r.runs {
381			if run.ID == id {
382				return run
383			}
384		}
385		return nil
386	}
387	
388	// settle stamps EndedAt the first time a run is found finished, and drops the
389	// oldest settled runs once there are more than the cap allows.
390	func (r *Registry) settle(run *Run) {
391		if run.Finished() && run.EndedAt.IsZero() {
392			run.EndedAt = r.now()
393		}
394		r.prune()
395	}
396	
397	// prune keeps at most MaxFinishedRuns settled runs, dropping the oldest first.
398	// A run still going is never dropped, whatever its age: the registry losing
399	// track of live work is the one failure that would leave a view spinning.
400	func (r *Registry) prune() {
