package jobs

import (
	"context"
	"time"
)

// MaxFinishedRuns is how many settled runs the registry keeps. Runs live for
// the session (D8) — they are not written anywhere and do not survive a
// restart — but a session that scans all day would otherwise grow a list
// nobody scrolls to the end of.
//
// Twenty is the count at which the oldest entry has stopped being useful: the
// question a jobs view answers about a finished run is "did that one work?",
// and it is asked about the last few.
const MaxFinishedRuns = 20

// Registry is the one place that knows what is running.
//
// It is **not safe for concurrent use, deliberately**. It is owned by the
// router and mutated from Update alone, which is where Rule 110 puts every
// write to application state; a mutex here would say a Cmd may touch it, and
// that is exactly the thing that must stay untrue. What a Cmd does is return a
// message, and Update turns that into a transition.
type Registry struct {
	runs   []*Run
	nextID JobID
	// clock is time.Now in production and a fixed hand in tests, so a run's
	// StartedAt is an assertion rather than a tolerance.
	clock func() time.Time
}

// New returns an empty registry.
func New() *Registry {
	return &Registry{clock: time.Now}
}

// SetClock replaces the registry's idea of now. It exists for tests.
func (r *Registry) SetClock(clock func() time.Time) { r.clock = clock }

// Start admits a run, stamps it and returns its identifier.
//
// The run arrives with every item queued and is registered from Update, at the
// moment the commands are dispatched — never from inside one (D10). Every
// launch site knows its full list of targets at that point, which is what makes
// "8 waiting" sayable at all.
func (r *Registry) Start(run Run) JobID {
	r.nextID++
	run.ID = r.nextID
	if run.StartedAt.IsZero() {
		run.StartedAt = r.now()
	}
	if run.Finished() {
		run.EndedAt = run.StartedAt
	}
	r.runs = append(r.runs, &run)
	r.prune()
	return run.ID
}

// Advance moves one item of a run to a new state.
//
// A transition addressed to a run or a target the registry does not hold is
// reported rather than ignored: it means a launch site emitted a message for
// work it never registered, and the visible symptom would be a row that spins
// for the life of the view — the failure this package exists to remove.
func (r *Registry) Advance(id JobID, target string, state ItemState, detail string) bool {
	return r.advance(id, target, state, detail, nil)
}

// advance is Advance with the cancel function a starting transition carries.
//
// It arrives here and not through a call of its own because the two are one
// event: the context is created inside the Cmd, so the function reaches Update
// in the very message that says the item started. Two calls would leave a
// window where the item is running and cannot be stopped.
func (r *Registry) advance(id JobID, target string, state ItemState, detail string, cancel context.CancelFunc) bool {
	run := r.run(id)
	if run == nil {
		return false
	}
	for i := range run.Items {
		if run.Items[i].Target != target {
			continue
		}
		run.Items[i].State = state
		run.Items[i].Detail = detail
		switch {
		case state.Terminal():
			run.Items[i].cancel = nil
		case cancel != nil:
			run.Items[i].cancel = cancel
		}
		r.settle(run)
		return true
	}
	return false
}

// Transition is what a progress message says about one target.
//
// It exists so the router can apply a message without knowing the vocabulary of
// the view that sent it. A sync that was refused because the tree is dirty is a
// skip with a reason; only the workspaces package knows that, and it says so by
// answering this — see Reporter.
type Transition struct {
	Kind   Kind
	Target string
	State  ItemState
	Detail string

	// Cancel stops the work this transition reports as started, and is nil for
	// every other transition and for the kinds that cannot be cut (D7).
	//
	// It travels on the transition rather than through a call of its own
	// because the two are one event: the context is created inside the Cmd, so
	// the function reaches Update in the message that says the item started.
	Cancel context.CancelFunc

	// Discover says the target has no row yet and belongs to the open run of
	// this kind (D3). Only a kind whose targets arrive progressively sets it —
	// the clone, whose walk is what finds them — and for every other kind it
	// stays false because the full list was known at launch.
	Discover bool
}

// Reporter is implemented by a message that reports on registered work.
//
// The alternative was a switch in the router mapping every view's outcome
// vocabulary onto item states, which puts each view's semantics in a file that
// belongs to none of them, and grows by one branch per view.
type Reporter interface {
	Transition() Transition
}

// Sealer is implemented by the message that says a kind's open run has found
// everything it is going to (D3).
//
// It is a second interface rather than a field on Transition because sealing
// names no target: the message that carries it is the closed event channel, and
// there is nothing for it to be about.
type Sealer interface {
	Seal() Kind
}

// Apply routes a transition to the run it belongs to. It reports whether one
// was found, which is how the router knows there is something new to broadcast.
func (r *Registry) Apply(t Transition) bool {
	if t.Discover {
		return r.Discover(t.Kind, t.Target, t.State, t.Detail)
	}
	id, ok := r.FindItem(t.Kind, t.Target)
	if !ok {
		return false
	}
	return r.advance(id, t.Target, t.State, t.Detail, t.Cancel)
}

// Discover adds a target to the open run of a kind (D3).
//
// A target already there is advanced instead of duplicated: the walk reports a
// group it could not list as a target of its own, and that path may also have
// been found as a repository. One row, whichever arrives first.
func (r *Registry) Discover(kind Kind, target string, state ItemState, detail string) bool {
	run := r.openRun(kind)
	if run == nil {
		return false
	}
	for i := range run.Items {
		if run.Items[i].Target == target {
			run.Items[i].State = state
			run.Items[i].Detail = detail
			r.settle(run)
			return true
		}
	}
	run.Items = append(run.Items, Item{Target: target, State: state, Detail: detail})
	r.settle(run)
	return true
}

// Seal says the open run of a kind has discovered everything it is going to.
//
// Until it is called the run is unsettled whatever its items say, which is the
// point: a walk that has found three repositories and cloned all three is not
// done. Sealing is what lets the run finish, stamp EndedAt and let the spinner
// chain die.
func (r *Registry) Seal(kind Kind) bool {
	run := r.openRun(kind)
	if run == nil {
		return false
	}
	run.open = false
	r.settle(run)
	return true
}

// CancelOpen stops the open run of a kind.
//
// It exists because a progressive run is the one case a view can name without
// a target: there is exactly one open run per kind at a time — the screen that
// owns it is exclusive while it goes — so "the clone I am looking at" resolves
// without the view holding a JobID, which is the thing D1 keeps out of views.
func (r *Registry) CancelOpen(kind Kind) bool {
	run := r.openRun(kind)
	if run == nil {
		return false
	}
	return r.Cancel(run.ID)
}

// openRun is the run of a kind that is still discovering, if there is one.
//
// At most one can exist: an open run belongs to a screen that owns the display
// while it goes, so a second could only be started by leaving that screen —
// which closes the first. The newest wins if that invariant is ever broken, so
// the answer is the run a user is looking at rather than one they have left.
func (r *Registry) openRun(kind Kind) *Run {
	for i := len(r.runs) - 1; i >= 0; i-- {
		if r.runs[i].Kind == kind && r.runs[i].open {
			return r.runs[i]
		}
	}
	return nil
}

// FindItem names the run a transition belongs to.
//
// The launch sites do not carry a JobID in their messages, and deliberately:
// a view would have to hold one, which means holding registry state — the thing
// D1 keeps out of the views — and it would have to hold it before the registry
// had allocated it. The router looks the run up instead, from what the message
// already says: the kind is decided by which message arrived, and the target is
// in it.
//
// The oldest unsettled run wins. Two live runs of one kind cannot hold the same
// target — that is what the busy() guards prevent, and they are answered from
// this registry now, so the exclusion is enforced rather than hoped for.
func (r *Registry) FindItem(kind Kind, target string) (JobID, bool) {
	for _, run := range r.runs {
		if run.Kind != kind || run.Finished() {
			continue
		}
		for i := range run.Items {
			if run.Items[i].Target == target && !run.Items[i].State.Terminal() {
				return run.ID, true
			}
		}
	}
	return 0, false
}

// AttachRun stores the cancel function that stops the run's queue, as opposed
// to one item's work.
func (r *Registry) AttachRun(id JobID, cancel context.CancelFunc) {
	if run := r.run(id); run != nil {
		run.cancel = cancel
	}
}

// Cancel asks a run to stop.
//
// What that means differs by kind, and the difference is not cosmetic (D7):
// the queue always stops, so nothing further starts, but work already in flight
// is only interrupted where interrupting it leaves nothing behind. A `git
// clone` is never cut — a cancelled one leaves half a repository on disk — and
// a delete is not cancellable at all, which is a guard the view carries
// (Kind.Cancellable).
//
// Queued items are marked skipped straight away: they will not run, and leaving
// them queued would keep the run reading as running forever.
func (r *Registry) Cancel(id JobID) bool {
	run := r.run(id)
	if run == nil || run.Finished() {
		return false
	}

	run.cancelled = true
	// A cancelled walk finds nothing more, so the run is sealed here: leaving
	// it open would keep it unsettled for the life of the session, spinner
	// chain and all, with nothing left that could ever close it.
	run.open = false
	if run.cancel != nil {
		run.cancel()
		run.cancel = nil
	}

	for i := range run.Items {
		switch run.Items[i].State {
		case ItemQueued:
			run.Items[i].State = ItemSkipped
			run.Items[i].Detail = "cancelled"
		case ItemRunning:
			// Asked to stop, not declared stopped: the item reports its own
			// outcome when it gets there. Claiming it settled here would race
			// the message that says how it actually ended.
			if run.Items[i].cancel != nil {
				run.Items[i].cancel()
				run.Items[i].cancel = nil
			}
		}
	}

	r.settle(run)
	return true
}

// CancelItem stops one target of a run, leaving the rest going.
//
// It is the narrow half of D7: the run-level Cancel stops the queue whatever
// the kind, and this cuts a single piece of work — which is only offered where
// cutting leaves nothing behind. The caller decides that (Run.ItemStoppable);
// this refuses only what it cannot do.
//
// A queued target is skipped outright, because it will not run. A running one
// is *asked* to stop and left running: it reports its own outcome when it gets
// there, and claiming it settled here would race the message that says how it
// actually ended — the same reason Cancel gives.
func (r *Registry) CancelItem(id JobID, target string) bool {
	run := r.run(id)
	if run == nil || run.Finished() {
		return false
	}
	for i := range run.Items {
		if run.Items[i].Target != target || run.Items[i].State.Terminal() {
			continue
		}
		if run.Items[i].State == ItemQueued {
			run.Items[i].State = ItemSkipped
			run.Items[i].Detail = "cancelled"
		} else if run.Items[i].cancel != nil {
			run.Items[i].cancel()
			run.Items[i].cancel = nil
		}
		r.settle(run)
		return true
	}
	return false
}

// Snapshot returns a copy of every run, oldest first.
//
// It is what JobsChangedMsg carries, and copying is what makes the broadcast
// honest: a view holds data, not a window onto state someone else is writing.
// The cancel functions are cleared on the way out — a snapshot cannot stop a
// job, which has to go through Cancel on the registry the router owns.
func (r *Registry) Snapshot() []Run {
	out := make([]Run, 0, len(r.runs))
	for _, run := range r.runs {
		copied := *run
		copied.cancel = nil
		copied.Items = make([]Item, len(run.Items))
		copy(copied.Items, run.Items)
		for i := range copied.Items {
			copied.Items[i].cancel = nil
		}
		out = append(out, copied)
	}
	return out
}

// Running counts the runs that have not settled. It is what decides whether the
// router keeps its spinner chain alive, and what the degraded footer line
// counts (D9).
func (r *Registry) Running() int {
	n := 0
	for _, run := range r.runs {
		if !run.Finished() {
			n++
		}
	}
	return n
}

// Len returns how many runs the registry holds, settled ones included.
func (r *Registry) Len() int { return len(r.runs) }

// run finds a run by identifier.
func (r *Registry) run(id JobID) *Run {
	for _, run := range r.runs {
		if run.ID == id {
			return run
		}
	}
	return nil
}

// settle stamps EndedAt the first time a run is found finished, and drops the
// oldest settled runs once there are more than the cap allows.
func (r *Registry) settle(run *Run) {
	if run.Finished() && run.EndedAt.IsZero() {
		run.EndedAt = r.now()
	}
	r.prune()
}

// prune keeps at most MaxFinishedRuns settled runs, dropping the oldest first.
// A run still going is never dropped, whatever its age: the registry losing
// track of live work is the one failure that would leave a view spinning.
func (r *Registry) prune() {
	finished := 0
	for _, run := range r.runs {
		if run.Finished() {
			finished++
		}
	}
	excess := finished - MaxFinishedRuns
	if excess <= 0 {
		return
	}

	kept := make([]*Run, 0, len(r.runs)-excess)
	for _, run := range r.runs {
		if excess > 0 && run.Finished() {
			excess--
			continue
		}
		kept = append(kept, run)
	}
	r.runs = kept
}

func (r *Registry) now() time.Time {
	if r.clock == nil {
		return time.Now()
	}
	return r.clock()
}

package app

import (
	"time"

	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// changedMsg is the snapshot the router broadcasts. It fills both readings of
// the frame — bare for a table cell (Rule 122), styled for a footer
// (Rule 128) — so the two cannot drift and internal/jobs needs to know nothing
// about styling.
func (a *App) changedMsg() jobs.ChangedMsg {
	frame := a.jobFrame()
	return jobs.ChangedMsg{
		Runs:          a.jobs.Snapshot(),
		Frame:         frame,
		RenderedFrame: theme.SpinnerStyle().Render(frame),
	}
}

// handleStartJobs admits a run a view built and asks the registry for it.
//
// The context is stamped here rather than by the view: the router is what knows
// which context is current, and a view reading it back from the configuration
// would be reading it again — which is the shape of the defect the stamp exists
// to close (a batch outliving a switch and writing into the new context's
// cache).
//
// The stamp is then handed to the work, which is the half that was missing
// (D68): a run carrying the right name while its commands re-read the current
// one told `:jobs` the truth and wrote the cache anyway. Building the work here
// means the name is read once, in Update, and every command of the batch shares
// the string — a switch three repositories later cannot reach it.
func (a *App) handleStartJobs(msg jobs.StartMsg) (tea.Model, tea.Cmd) {
	run := msg.Run
	run.Context = a.currentContext
	id := a.jobs.Start(run)
	if msg.Cancel != nil {
		a.jobs.AttachRun(id, msg.Cancel)
	}
	// The work goes out after the registration, which is the whole reason it
	// travels on the message: a transition naming a run the registry has not
	// admitted yet is refused, and the row would spin for the life of the view.
	cmds := []tea.Cmd{a.jobsChanged()}
	if msg.Work != nil {
		cmds = append(cmds, msg.Work(run.Context))
	}
	return a, tea.Batch(cmds...)
}

// routeWork applies a progress message to the registry and hands it to the view
// that owns it.
//
// The registry is written **before** the view sees the message, so the view is
// reading a current snapshot when it handles it — which is what lets it ask
// "has my batch finished?" rather than counting alongside.
//
// A message that reports on work nobody registered is still routed: the view
// has its own reasons to see it, and Apply already returned false rather than
// inventing a run for it.
func (a *App) routeWork(target command.ViewType, msg tea.Msg) (tea.Model, tea.Cmd) {
	var cmds []tea.Cmd
	if reporter, ok := msg.(jobs.Reporter); ok {
		if a.jobs.Apply(reporter.Transition()) {
			cmds = append(cmds, a.jobsChanged())
		}
	}
	// A sealer says a progressive run has found everything it is going to
	// (D3). It is a second interface because sealing names no target — the
	// message carrying it is a closed channel, and there is nothing for it to
	// be about.
	if sealer, ok := msg.(jobs.Sealer); ok {
		if a.jobs.Seal(sealer.Seal()) {
			cmds = append(cmds, a.jobsChanged())
		}
	}
	_, cmd := a.routeToView(target, msg)
	return a, tea.Batch(append(cmds, cmd)...)
}

// handleCancelOpen stops the open run of a kind and tells every view.
//
// The view that asked is updated by the broadcast like any other, so it does
// not have to keep its own idea of "cancelling" in step with the registry's.
func (a *App) handleCancelOpen(msg jobs.CancelOpenMsg) (tea.Model, tea.Cmd) {
	if !a.jobs.CancelOpen(msg.Kind) {
		return a, nil
	}
	return a, a.jobsChanged()
}

// handleCancel stops a run named by identifier, and handleCancelItem one of its
// targets (D7).
//
// The identifier comes from the snapshot the asking view is rendering, which is
// what makes it addressable at all: a launch site could not hold one — it would
// have to before the registry allocated it — but `:jobs` reads it off the row
// the cursor is on.
//
// A refusal is silent here, and it is not a swallowed error: the view asked
// only because its own guard said it could (Rule 130), so a false answer means
// the run settled between the keypress and this handler. There is nothing to
// tell the user that the next broadcast will not say better.
func (a *App) handleCancel(msg jobs.CancelMsg) (tea.Model, tea.Cmd) {
	if !a.jobs.Cancel(msg.ID) {
		return a, nil
	}
	return a, a.jobsChanged()
}

func (a *App) handleCancelItem(msg jobs.CancelItemMsg) (tea.Model, tea.Cmd) {
	if !a.jobs.CancelItem(msg.ID, msg.Target) {
		return a, nil
	}
	return a, a.jobsChanged()
}

// jobTickMsg advances the one spinner frame the whole application shares.
//
// It is the router's own message type rather than a spinner.TickMsg on purpose.
// bubbles keeps chains apart with an id and a tag, which works, but it means a
// stray tick from any view is something this handler would have to recognise
// and decline. A message nobody else sends cannot be confused with anything.
type jobTickMsg struct {
	// seq identifies the chain. A tick from an older one is dropped, which is
	// what makes a second chain impossible rather than merely unlikely — the
	// failure the four hand-stamped spinners kept producing was two chains
	// advancing the same frame at twice the rate.
	seq int
}

// jobSpinnerInterval is the cadence of the shared frame. It is taken from the
// same spinner the views used, so the animation does not change speed on the
// day a view stops stamping its own.
//
// It is a var rather than a const for one reason: testutil.FastTimers shortens
// it for the length of a test, the way components.FooterMsgDuration is. A test
// that drains the chain would otherwise sleep a tenth of a second per tick.
var jobSpinnerInterval = spinner.Dot.FPS

func jobTick(seq int) tea.Cmd {
	return tea.Tick(jobSpinnerInterval, func(time.Time) tea.Msg {
		return jobTickMsg{seq: seq}
	})
}

// jobFrame returns the current bare frame.
func (a *App) jobFrame() string {
	frames := spinner.Dot.Frames
	return frames[a.jobFrameIdx%len(frames)]
}

// jobsChanged is what a launch site or a transition calls once it has written
// to the registry: it tells every view, and makes sure the frame is moving.
//
// Both halves are needed and neither implies the other — a run that starts
// while another is already going changes the snapshot without needing a second
// chain, and a run that settles changes the snapshot while the chain must be
// allowed to die.
func (a *App) jobsChanged() tea.Cmd {
	return tea.Batch(a.broadcastJobs(), a.ensureJobTick())
}

// broadcastJobs hands the current snapshot to every view the router holds, on
// screen or not.
//
// Every view and not just the active one: a view is updated where it stands so
// that coming back to it shows what happened while it was away, without it
// having to ask. The cost is one Update per held view per frame, and a view's
// Update returns on the first type switch for a message it does not know.
//
// The layout is re-measured once at the end rather than per view, for the same
// reason forwardToActiveView measures at all: a footer that grew a line has to
// be given it (Rule 124). Only the view on screen can change the height, so one
// check covers the loop.
func (a *App) broadcastJobs() tea.Cmd {
	msg := a.changedMsg()

	cmds := make([]tea.Cmd, 0, len(a.views))
	for name, view := range a.views {
		updated, cmd := view.Update(msg)
		a.views[name] = updated
		if cmd != nil {
			cmds = append(cmds, cmd)
		}
	}

	if newFooterHeight := a.getFooterHeight(); newFooterHeight != a.lastFooterHeight {
		a.resize(a.width, a.height)
	}
	return tea.Batch(cmds...)
}

// sendJobsTo hands the snapshot to one view, which is what a view entering the
// screen needs: it was updated where it stood, but a view built lazily on the
// way in was not there for any of it.
func (a *App) sendJobsTo(target command.ViewType) tea.Cmd {
	view, ok := a.views[target]
	if !ok {
		return nil
	}
	updated, cmd := view.Update(a.changedMsg())
	a.views[target] = updated
	return cmd
}

// ensureJobTick starts the shared chain if work is running and no chain is
// alive. It is the one place a chain is ever started (D5).
func (a *App) ensureJobTick() tea.Cmd {
	if a.jobTicking || a.jobs.Running() == 0 {
		return nil
	}
	a.jobTicking = true
	a.jobTickSeq++
	return jobTick(a.jobTickSeq)
}

// handleJobTick advances the shared frame and schedules the next one, for as
// long as there is something to animate.
//
// The chain stops by not being renewed, and `jobTicking` is what lets the next
// run start a new one. Renewing it against an empty registry would rebuild
// every view's rows ten times a second for a settled application — which is the
// reason each view stopped its own chain, and, having no way to restart it,
// left its spinner frozen on the frame it died at.
func (a *App) handleJobTick(msg jobTickMsg) (tea.Model, tea.Cmd) {
	if msg.seq != a.jobTickSeq {
		return a, nil
	}
	if a.jobs.Running() == 0 {
		a.jobTicking = false
		return a, nil
	}
	a.jobFrameIdx = (a.jobFrameIdx + 1) % len(spinner.Dot.Frames)
	return a, tea.Batch(a.broadcastJobs(), jobTick(a.jobTickSeq))
}

package explorer

import "github.com/anthnel/devdesk/internal/jobs"

// What each clone event tells the registry (jobs.Reporter).
//
// The mapping lives here and not in the router, for the reason Reporter exists:
// "a repository that was already on disk is a skip, and it is not news" is this
// package's vocabulary, and a router that knew it would grow a branch per view.
//
// cloneFound and cloneWalkFailed both set Discover, because both name a target
// the run has never heard of — the walk is what finds them (D3). The others
// address a row that exists.

func (m CloneEventMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindClone, Target: m.event.path}
	switch m.event.kind {
	case cloneFound:
		t.State, t.Discover = jobs.ItemQueued, true
	case cloneBegan:
		t.State = jobs.ItemRunning
	case cloneEnded:
		switch {
		case m.event.err != nil:
			t.State, t.Detail = jobs.ItemFailed, m.event.err.Error()
		case m.event.skipped:
			// Not a failure and not work: the directory was already there, and
			// decision 2 says the explorer leaves what exists alone.
			t.State = jobs.ItemSkipped
		default:
			t.State = jobs.ItemDone
		}
	case cloneWalkFailed:
		// A group that could not be listed gets a row of its own rather than
		// being folded into a repository's error: the repositories under it
		// were never discovered, so no other row can stand for them. It is
		// discovered *as* a failure — there was never a queued state for it.
		t.State, t.Detail, t.Discover = jobs.ItemFailed, "discovery: "+m.event.err.Error(), true
	}
	return t
}

// Seal says the walk is over (jobs.Sealer). Until it is called the run is
// unsettled whatever its rows say: a walk that has found three repositories and
// cloned all three is not done.
func (CloneRunFinishedMsg) Seal() jobs.Kind { return jobs.KindClone }

// Compile-time proof that the two messages carry what the registry needs. One
// added without it would be routed, would update the view, and would leave its
// row spinning for the life of the screen.
var (
	_ jobs.Reporter = CloneEventMsg{}
	_ jobs.Sealer   = CloneRunFinishedMsg{}
)

package explorer

import (
	"log"
	"strconv"
	"strings"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/forge"
	"github.com/anthnel/devdesk/internal/jobs"
)

// The clone flow, end to end (§3.16):
//
//	c              → ModeSelecting, the tree with checkboxes
//	space          → tick the row; ←→ still drill, so deselecting means going in
//	enter          → borrow the workspaces view for a destination
//	                 (the selection survives the round trip — it names paths)
//	destination    → ModeCloning, the pipeline starts
//	esc            → cancel: discovery stops, running clones are awaited
//	esc (finished) → back to the tree, list discarded (decision 13)

// handleCloneStart enters the selection mode.
func (m Model) handleCloneStart() (tea.Model, tea.Cmd) {
	if !m.shared.IsAuthenticated || len(m.nodes) == 0 {
		return m, nil
	}
	m.mode = ModeSelecting
	m.selection = newCloneSelection()
	m.selectionNodes = map[string]*TreeNode{}
	m.updateTableRows()
	return m, nil
}

// handleSelectionToggle ticks or unticks the row under the cursor (Space,
// Rule 135).
//
// The node is kept beside the path because the walk needs somewhere to start
// and a root ticked three levels down is not reachable from the current level
// once the user has come back up. The selection itself stays paths-only — it
// has to answer for descendants nobody has fetched.
func (m Model) handleSelectionToggle() (tea.Model, tea.Cmd) {
	node, ok := m.selectedNode()
	if !ok {
		return m, nil
	}
	// A row the forge has not confirmed cannot be cloned — there is nothing at
	// that path yet — and refusing it here is what lets the icon column give
	// the spinner priority over the checkbox without the two ever competing.
	if act := m.actionable(); !act.Enabled() {
		return m, m.footer.Warn(act.Reason)
	}

	m.selection.toggle(node.FullPath)
	if m.selection.isRoot(node.FullPath) {
		m.selectionNodes[node.FullPath] = node
	} else {
		delete(m.selectionNodes, node.FullPath)
	}
	m.updateTableRows()
	return m, nil
}

// handleSelectionConfirm asks the app for a destination directory.
func (m Model) handleSelectionConfirm() (tea.Model, tea.Cmd) {
	if m.selection.isEmpty() {
		return m, m.footer.Warn("Nothing selected — press space to tick a group or a project")
	}
	return m, func() tea.Msg { return CloneSelectionRequestMsg{} }
}

// handleSelectionCancel leaves the selection mode, dropping the selection.
func (m Model) handleSelectionCancel() (tea.Model, tea.Cmd) {
	m.mode = ModeNormal
	m.selection = newCloneSelection()
	m.selectionNodes = nil
	m.updateTableRows()
	return m, nil
}

// handleCloneDestinationSelected starts the pipeline.
func (m Model) handleCloneDestinationSelected(msg CloneDestinationSelectedMsg) (tea.Model, tea.Cmd) {
	roots := m.rootNodes()
	if len(roots) == 0 {
		// The selection survived the round trip but named nothing reachable,
		// which is a bug rather than a user action — say so instead of opening
		// an empty list.
		log.Printf("ERROR [explorer] clone: the selection resolved to no nodes")
		cancelled, _ := m.handleSelectionCancel()
		m = cancelled.(Model)
		return m, m.footer.Error("Nothing to clone — check logs")
	}

	run := startCloneRun(cloneSpec{
		backend:         m.shared.Forge,
		roots:           roots,
		selection:       m.selection,
		target:          msg.Path,
		secrets:         m.shared.Secrets.Storage,
		cloneMethod:     forge.CloneMethod(m.config.Forge.CloneMethod),
		gitlabURL:       m.config.Forge.URL,
		jobs:            m.config.Forge.Pull.ParallelJobs,
		includeArchived: m.config.Forge.Pull.IncludeArchived,
	})

	m.mode = ModeCloning
	m.clone = newCloneList(msg.Path, run.events)
	m.clone.table.Resize(m.width, max(m.height-1, 1))
	// An **open** run: the walk that finds repositories is itself the slow
	// part, so there is no target list to register (D3). The cancel travels
	// with it because the pipeline was started here, in Update — which is also
	// what makes `esc` reach the registry rather than the channel behind its
	// back.
	return m, tea.Batch(
		jobs.StartCancellable(m.cloneJobRun(msg.Path), waitForCloneEvent(run.events), run.cancel),
		m.spinner.Tick,
	)
}

// cloneRun describes the batch to the registry. The destination names it: it is
// what a human recognises a clone by, and the roots are already in the rows.
func (m Model) cloneJobRun(target string) jobs.Run {
	return jobs.NewOpenRun(jobs.KindClone, command.ViewGitExplorer, "", target)
}

// rootNodes resolves the ticked paths to the nodes the walk starts from, in a
// stable order so two runs of the same selection read the same way.
func (m Model) rootNodes() []*TreeNode {
	paths := m.selection.rootPaths()
	nodes := make([]*TreeNode, 0, len(paths))
	for _, path := range paths {
		if node, ok := m.selectionNodes[path]; ok {
			nodes = append(nodes, node)
		}
	}
	return nodes
}

// handleCloneEvent logs what deserves logging and waits for the next event.
//
// It no longer folds anything in: the router applied the event to the registry
// before handing it here, and the rows arrive in the broadcast that follows
// (D1). What is left is the log and the re-issued read.
func (m Model) handleCloneEvent(msg CloneEventMsg) (tea.Model, tea.Cmd) {
	if m.clone == nil {
		return m, nil
	}
	if msg.event.kind == cloneEnded && msg.event.err != nil {
		log.Printf("ERROR [explorer] clone %s: %v", msg.event.path, msg.event.err)
	}
	if msg.event.kind == cloneWalkFailed {
		log.Printf("ERROR [explorer] discover %s: %v", msg.event.path, msg.event.err)
	}
	return m, waitForCloneEvent(m.clone.events)
}

// handleCloneRunFinished is the closed channel: the walk is over and every
// clone has returned. The router has sealed the run by the time this runs.
func (m Model) handleCloneRunFinished() (tea.Model, tea.Cmd) {
	if m.clone == nil {
		return m, nil
	}

	// Decision 13 keeps only what workspaces can show, and a failed clone wrote
	// nothing. Naming the failures now is the only record there will be.
	if failed := m.clone.failures(); len(failed) > 0 {
		return m, m.footer.Error(failureSummary(failed))
	}
	return m, nil
}

// handleJobsChanged takes the router's snapshot.
//
// Two screens read it now. The clone list reads its own run, and the tree reads
// the creates and deletes running against the rows it is showing — liveRuns is
// what keeps a scan in `ws` from spinning a row here, rather than this handler
// declining to keep the snapshot at all.
//
// It is the only writer of the two fields, and there is nothing to reconcile:
// the snapshot replaces what was held rather than being merged into it.
func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
	m.jobs = msg.Runs
	m.jobFrame = msg.Frame
	m.footer.SetSpinnerFrame(msg.RenderedFrame)

	if m.clone != nil {
		if run, ok := cloneRunFrom(msg.Runs); ok {
			m.clone.setRun(run, msg.Frame)
		}
		return m, nil
	}
	// The frame moved, so the rows carrying it have to be rebuilt.
	m.updateTableRows()
	return m, nil
}

// failureSummary names one failure and counts the rest — the footer is one line.
func failureSummary(failed []string) string {
	if len(failed) == 1 {
		return "Failed to clone " + failed[0] + " — check logs"
	}
	return "Failed to clone " + failed[0] + " and " +
		plural(len(failed)-1, "other") + " — check logs"
}

func plural(n int, word string) string {
	if n == 1 {
		return "1 " + word
	}
	return strconv.Itoa(n) + " " + word + "s"
}

// handleCloneEsc cancels a running pipeline, or closes a finished one.
//
// The two are one key because they are one intent — "I am done with this" — and
// separating them would need the user to know which state the list is in. A
// second press while cancelling does nothing: forcing would mean killing a
// `git clone` mid-write, which is the half-repository decision 12 rules out.
func (m Model) handleCloneEsc() (tea.Model, tea.Cmd) {
	if m.clone == nil {
		m.mode = ModeNormal
		return m, nil
	}
	if m.clone.finished() {
		return m.handleCloneClose()
	}
	if m.clone.cancelling {
		return m, nil
	}

	// The registry stops the run: it holds the cancel, and it is what marks the
	// run cancelled so `:jobs` says "cancelled" rather than "done". Calling the
	// pipeline's cancel from here would stop the walk behind the registry's
	// back, and leave the record claiming the run finished on its own.
	m.clone.cancelling = true
	return m, jobs.CancelOpen(jobs.KindClone)
}

// handleCloneClose discards the list and returns to the tree.
func (m Model) handleCloneClose() (tea.Model, tea.Cmd) {
	m.clone = nil
	m.selection = newCloneSelection()
	m.selectionNodes = nil
	m.mode = ModeNormal
	m.updateTableRows()
	return m, nil
}

// cloneStatusLine is what the view puts under the list: what the run is doing,
// then what it did.
func (m Model) cloneStatusLine() string {
	if m.clone == nil {
		return ""
	}
	found, cloned, present, failed := m.clone.counts()

	var b strings.Builder
	switch {
	case m.clone.finished():
		b.WriteString("Done — ")
	case m.clone.cancelling:
		b.WriteString("Cancelling — " + plural(m.clone.running(), "clone") + " finishing · ")
	default:
		b.WriteString(strconv.Itoa(found) + " found · ")
	}
	b.WriteString(strconv.Itoa(cloned) + " cloned · " + strconv.Itoa(present) + " already there")
	if failed > 0 {
		b.WriteString(" · " + strconv.Itoa(failed) + " failed")
	}
	return b.String()
}

