1	package ociresources
2	
3	import (
4		tea "github.com/charmbracelet/bubbletea"
5	
6		"github.com/anthnel/devdesk/internal/command"
7		"github.com/anthnel/devdesk/internal/docker"
8		"github.com/anthnel/devdesk/internal/jobs"
9		"github.com/anthnel/devdesk/internal/ui/registryalias"
10	)
11	
12	// What is being scanned is the registry's answer, not this view's (§3.58).
13	//
14	// It held a `scanningImages` map and a `scanning` bool derived from it, and both
15	// knew only what this view had launched. An image scanned from `:sec` — the same
16	// image, the same cache entry — went unnoticed here, so `S` offered itself on a
17	// row already being scanned and the two wrote the same file.
18	//
19	// The view's own `spinner.Model` stays, and deliberately: it animates *loading*
20	// — the image list, the networks, a `docker` action on a row — and a load is not
21	// a job. What moved is the frame the scan cells use, which now comes from the
22	// one chain the router holds (D5).
23	
24	// handleJobsChanged takes the router's snapshot. It is the only writer of the
25	// two fields.
26	func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
27		m.jobs = msg.Runs
28		m.jobFrame = msg.Frame
29		// The footer's spinner is deliberately not touched: here it belongs to
30		// *loading* — a tab reading its list — and this view's scan progress is on
31		// the rows, not in the footer. Two writers of one field would fight every
32		// frame a scan and a load overlapped.
33		m.updateImageTable()
34		if m.registryBrowser != nil {
35			m.registryBrowser.SetTagScanningSet(m.scanningNames())
36		}
37		return m, nil
38	}
39	
40	// scanRun builds the run behind S, A, ctrl+a and a direct scan from the browser.
41	func (m Model) scanRun(names []string) jobs.Run {
42		run := jobs.NewRun(jobs.KindScan, command.ViewOCIResources, "", "images", names...)
43		// The alias is applied here rather than by whoever shows the run: it is
44		// this view's configuration that defines it, and `:jobs` has no business
45		// reading a registry list to print a name.
46		aliases := registryalias.From(m.registries)
47		for _, name := range names {
48			if display := docker.ApplyAliases(name, aliases); display != name {
49				run = run.WithDisplay(name, display)
50			}
51		}
52		return run
53	}
54	
55	// scanningImage reports whether an image is queued or being scanned, whoever
56	// started it.
57	func (m Model) scanningImage(name string) bool {
58		for _, run := range jobs.Unfinished(m.jobs) {
59			if run.Kind != jobs.KindScan {
60				continue
61			}
62			for _, item := range run.Items {
63				if item.Target == name && !item.State.Terminal() {
64					return true
65				}
66			}
67		}
68		return false
69	}
70	
71	// scanningNames lists every image with a scan in flight, for the registry
72	// browser, which decorates its tag rows from the same source.
73	func (m Model) scanningNames() map[string]bool {
74		out := make(map[string]bool)
75		for _, run := range jobs.Unfinished(m.jobs) {
76			if run.Kind != jobs.KindScan {
77				continue
78			}
79			for _, item := range run.Items {
80				if !item.State.Terminal() {
81					out[item.Target] = true
82				}
83			}
84		}
85		return out
86	}
87	
88	// anyScanRunning reports whether a scan is going anywhere. It is what A and
89	// ctrl+a refuse on, and it is true for a scan this view did not start — which
90	// is the point: the two would write the same cache entries.
91	func (m Model) anyScanRunning() bool { return len(m.scanningNames()) > 0 }
92	
93	// ── What each message tells the registry (jobs.Reporter) ─────────────────────
94	
95	func (m ImageScanStartingMsg) Transition() jobs.Transition {
96		return jobs.Transition{Kind: jobs.KindScan, Target: m.ImageName, State: jobs.ItemRunning, Cancel: m.Cancel}
97	}
98	
99	func (m ImageScanFinishedMsg) Transition() jobs.Transition {
100		t := jobs.Transition{Kind: jobs.KindScan, Target: m.ImageName, State: jobs.ItemDone}
101		if m.Err != nil {
102			t.State = jobs.ItemFailed
103			t.Detail = "scan failed — check logs"
104		}
105		return t
106	}
107	
108	// Compile-time proof that both progress messages can be applied. One added
109	// without a transition would leave its row spinning for the life of the view.
110	var (
111		_ jobs.Reporter = ImageScanStartingMsg{}
112		_ jobs.Reporter = ImageScanFinishedMsg{}
113	)
