53	// deleteScanCacheCmd removes the given image keys from the disk cache (Rule 126: scan all purges cache)
54	func deleteScanCacheCmd(keys []string) tea.Cmd {
55		return func() tea.Msg {
56			c, err := cache.NewImageScanCache()
57			if err != nil {
58				return nil
59			}
60			for _, key := range keys {
61				_ = c.Delete(key)
62			}
63			return nil
64		}
65	}
