315		return func() tea.Msg {
316			c, err := cache.NewLaunchOptionsCache()
317			if err != nil {
318				log.Printf("ERROR [oci_resources] open launch options cache: %v", err)
319				return nil
320			}
321			if err := c.Set(imageKey, entry); err != nil {
