336	// verifyEntrypointCmd checks if an entrypoint binary exists inside an image.
337	// Uses a 600ms debounce delay so rapid keystrokes don't flood docker.
338	// The seq parameter guards against stale results: results are discarded if seq
339	// no longer matches the form's current verifySeq when the message is received.
340	func verifyEntrypointCmd(seq int, image, entrypoint string) tea.Cmd {
341		return func() tea.Msg {
342			time.Sleep(600 * time.Millisecond)
343			ok, _ := docker.VerifyEntrypoint(image, entrypoint)
344			return EntrypointVerifyFinishedMsg{Seq: seq, OK: ok}
345		}
346	}
347	
348	// ---- Registry browser commands ----
349	
350	var ociHTTPClient = &http.Client{Timeout: 15 * time.Second}
351	
352	// registryAPIURL converts a user-specified registry URL into a v2 API base URL.
353	//
354	// This is the one place that *keeps* a scheme rather than stripping it: an
355	// explicit `http://` is how a registry on a plain-HTTP port is reached, and
356	// upgrading it would break that registry rather than fix anything. Everything
357	// Docker-facing goes through registryHost instead (D39).
358	func registryAPIURL(registryURL string) string {
359		base := strings.TrimSuffix(strings.TrimSpace(registryURL), "/")
360		if isDockerHub(base) {
361			return "https://registry-1.docker.io"
362		}
363		lower := strings.ToLower(base)
364		if !strings.HasPrefix(lower, "http://") && !strings.HasPrefix(lower, "https://") {
365			return "https://" + base
366		}
367		return base
368	}
369	
370	// doRegistryGETBytes performs a GET on rawURL, handling bearer token auth on 401.
371	func doRegistryGETBytes(rawURL, username, password string) ([]byte, error) {
372		req, err := http.NewRequest("GET", rawURL, nil)
373		if err != nil {
374			return nil, fmt.Errorf("build request: %w", err)
375		}
376		if username != "" && password != "" {
377			req.SetBasicAuth(username, password)
378		}
379		resp, err := ociHTTPClient.Do(req)
380		if err != nil {
381			return nil, fmt.Errorf("GET %s: %w", rawURL, err)
382		}
383		defer func() { _ = resp.Body.Close() }()
384	
385		if resp.StatusCode == http.StatusUnauthorized {
386			wwwAuth := resp.Header.Get("Www-Authenticate")
387			if !strings.HasPrefix(wwwAuth, "Bearer ") {
388				return nil, fmt.Errorf("unexpected auth challenge: %s", wwwAuth)
389			}
390			token, tErr := exchangeBearerToken(wwwAuth[7:], username, password)
391			if tErr != nil {
392				return nil, tErr
393			}
394			req2, err := http.NewRequest("GET", rawURL, nil)
395			if err != nil {
396				return nil, fmt.Errorf("build retry request: %w", err)
397			}
398			req2.Header.Set("Authorization", "Bearer "+token)
399			resp2, err := ociHTTPClient.Do(req2)
400			if err != nil {
401				return nil, fmt.Errorf("GET (retry) %s: %w", rawURL, err)
402			}
403			defer func() { _ = resp2.Body.Close() }()
404			if resp2.StatusCode != http.StatusOK {
405				return nil, fmt.Errorf("registry returned %d", resp2.StatusCode)
406			}
407			return io.ReadAll(resp2.Body)
408		}
409		if resp.StatusCode != http.StatusOK {
410			return nil, fmt.Errorf("registry returned %d", resp.StatusCode)
411		}
412		return io.ReadAll(resp.Body)
413	}
414	
415	// exchangeBearerToken fetches a bearer token from the registry's token endpoint.
416	func exchangeBearerToken(challenge, username, password string) (string, error) {
417		params := parseBearerChallenge(challenge)
418		realm, ok := params["realm"]
419		if !ok {
420			return "", fmt.Errorf("bearer challenge missing realm")
421		}
422		u, err := url.Parse(realm)
423		if err != nil {
424			return "", fmt.Errorf("parse realm %q: %w", realm, err)
425		}
426		q := u.Query()
427		if s, ok := params["service"]; ok {
428			q.Set("service", s)
429		}
430		if s, ok := params["scope"]; ok {
431			q.Set("scope", s)
432		}
433		u.RawQuery = q.Encode()
434	
435		req, err := http.NewRequest("GET", u.String(), nil)
436		if err != nil {
437			return "", fmt.Errorf("build token request: %w", err)
438		}
439		if username != "" && password != "" {
440			req.SetBasicAuth(username, password)
441		}
442		resp, err := ociHTTPClient.Do(req)
443		if err != nil {
444			return "", fmt.Errorf("fetch token: %w", err)
445		}
446		defer func() { _ = resp.Body.Close() }()
447		if resp.StatusCode != http.StatusOK {
448			return "", fmt.Errorf("token endpoint returned %d", resp.StatusCode)
449		}
450		body, err := io.ReadAll(resp.Body)
451		if err != nil {
452			return "", fmt.Errorf("read token response: %w", err)
453		}
454		var result struct {
455			Token       string `json:"token"`
456			AccessToken string `json:"access_token"`
457		}
458		if err := json.Unmarshal(body, &result); err != nil {
459			return "", fmt.Errorf("decode token response: %w", err)
460		}
461		if result.Token != "" {
462			return result.Token, nil
463		}
464		if result.AccessToken != "" {
465			return result.AccessToken, nil
466		}
467		return "", fmt.Errorf("token response contained no token field")
468	}
469	
470	// parseBearerChallenge parses the value portion of a Www-Authenticate: Bearer header.
471	// Example: `realm="https://auth.docker.io/token",service="registry.docker.io"`
472	func parseBearerChallenge(s string) map[string]string {
473		params := make(map[string]string)
474		for _, part := range strings.Split(s, ",") {
475			part = strings.TrimSpace(part)
476			idx := strings.IndexByte(part, '=')
477			if idx < 0 {
478				continue
479			}
480			key := strings.TrimSpace(part[:idx])
481			val := strings.Trim(strings.TrimSpace(part[idx+1:]), `"`)
482			params[key] = val
483		}
484		return params
485	}
486	
487	// fetchRegistryTags fetches the tag list for a repository from the registry API.
488	func fetchRegistryTags(apiURL, repo, username, password string) ([]string, error) {
489		endpoint := fmt.Sprintf("%s/v2/%s/tags/list", strings.TrimSuffix(apiURL, "/"), repo)
490		body, err := doRegistryGETBytes(endpoint, username, password)
491		if err != nil {
492			return nil, err
493		}
494		var result struct {
495			Tags []string `json:"tags"`
496		}
497		if err := json.Unmarshal(body, &result); err != nil {
498			return nil, fmt.Errorf("decode tags response: %w", err)
499		}
500		return result.Tags, nil
501	}
502	
503	// searchRegistryTagsCmd fetches tags from one registry and returns a MultiRegistryTagsLoadedMsg.
504	func searchRegistryTagsCmd(entryKey, registryURL, alias, apiURL, repo, username, password string) tea.Cmd {
505		return func() tea.Msg {
506			tags, err := fetchRegistryTags(apiURL, repo, username, password)
507			return MultiRegistryTagsLoadedMsg{
508				EntryKey: entryKey, RegistryURL: registryURL, Alias: alias, Repo: repo, Tags: tags, Err: err,
509			}
510		}
511	}
512	
513	// fetchDockerHubTagsMeta fetches last_updated times from the Docker Hub public API.
514	// Works for public repos (no auth needed). Returns partial results on error.
515	func fetchDockerHubTagsMeta(namespace, repo string) (map[string]time.Time, error) {
516		endpoint := fmt.Sprintf("https://hub.docker.com/v2/repositories/%s/%s/tags?page_size=100&ordering=last_updated", namespace, repo)
517		req, err := http.NewRequest("GET", endpoint, nil)
518		if err != nil {
519			return nil, err
520		}
521		req.Header.Set("Accept", "application/json")
522		resp, err := ociHTTPClient.Do(req)
523		if err != nil {
524			return nil, err
525		}
526		defer func() { _ = resp.Body.Close() }()
527		if resp.StatusCode != http.StatusOK {
528			return nil, fmt.Errorf("hub API returned %d", resp.StatusCode)
529		}
530		body, err := io.ReadAll(resp.Body)
531		if err != nil {
532			return nil, err
533		}
534		var result struct {
535			Results []struct {
536				Name        string `json:"name"`
537				LastUpdated string `json:"last_updated"`
538			} `json:"results"`
539		}
540		if err := json.Unmarshal(body, &result); err != nil {
541			return nil, err
542		}
543		meta := make(map[string]time.Time, len(result.Results))
544		for _, r := range result.Results {
545			if t, err := time.Parse(time.RFC3339Nano, r.LastUpdated); err == nil {
546				meta[r.Name] = t
547			}
548		}
549		return meta, nil
550	}
551	
552	// loadMultiRegistryTagsMetaCmd fetches tag metadata for one registry in the background.
553	// For Docker Hub it uses the Hub API; other registries return empty (no error).
554	func loadMultiRegistryTagsMetaCmd(entryKey, registryURL, repo string) tea.Cmd {
555		return func() tea.Msg {
556			empty := MultiRegistryTagsMetaMsg{EntryKey: entryKey, RegistryURL: registryURL, Repo: repo}
557			base := strings.ToLower(strings.TrimSuffix(registryURL, "/"))
558			isDockerhub := base == "docker.io" || base == "registry-1.docker.io"
559			if !isDockerhub {
560				return empty
561			}
562			parts := strings.SplitN(repo, "/", 2)
563			if len(parts) != 2 {
564				return empty
565			}
566			meta, err := fetchDockerHubTagsMeta(parts[0], parts[1])
567			return MultiRegistryTagsMetaMsg{
568				EntryKey: entryKey, RegistryURL: registryURL, Repo: repo, Meta: meta, Err: err,
569			}
570		}
571	}
572	
573	// pullRegistryImageCmd pulls a Docker image to the local store.
574	func pullRegistryImageCmd(imageName string) tea.Cmd {
575		return func() tea.Msg {
576			err := docker.PullImage(imageName)
577			return RegistryPullCompleteMsg{ImageName: imageName, Err: err}
578		}
579	}
580	
581	// detectRegistryGroupCmd calls the generic registrymgr.DetectGroup to determine
582	// whether reg is a group repository and enumerate its members.
583	// Always emits RegistryGroupDetectedMsg (Members==nil means not a group).
584	func detectRegistryGroupCmd(reg config.RegistryItem, password string) tea.Cmd {
585		return func() tea.Msg {
586			ctx, cancel := context.WithTimeout(context.Background(), 8*time.Second)
587			defer cancel()
588	
589			username := reg.Username
590			// D12: a registry the user marked anonymous is probed anonymously.
591			// Docker keys credentials by host, so without this gate the credentials
592			// stored for any registry on that host went out to all of them — which,
593			// for a Nexus instance, is every repository it serves.
594			if config.UsesCredentials(config.ResolveAuthMode(reg, nil)) {
595				username, password = discoveryCreds(reg, username, password)
596			} else {
597				username, password = "", ""
598			}
599	
600			info := registrymgr.RegistryInfo{
601				Provider:      reg.Provider,
602				URL:           reg.URL,
603				ManagementURL: reg.ManagementURL,
604				Username:      username,
605				Password:      password,
606			}
607			members, err := registrymgr.DetectGroup(ctx, info)
608			if err == nil {
609				cacheGroupMembers(reg.Slug, members)
610			}
611			return RegistryGroupDetectedMsg{RegistryURL: reg.URL, Slug: reg.Slug, Members: members, Err: err}
612		}
613	}
614	
615	// cacheGroupMembers records what a discovery found, so the next open reads it
616	// from disk instead of the network (§3.8, decision 3).
617	//
618	// A discovery that found nothing is stored too: "asked, and it is not a group"
619	// is an answer, and not storing it is what makes a non-group get probed forever.
620	// An error is not stored — an unreachable manager must not overwrite what was
621	// last known.
622	func cacheGroupMembers(slug string, members []registrymgr.GroupMember) {
623		if slug == "" {
624			return
625		}
626		c, err := cache.NewRegistryGroupCache()
627		if err != nil {
628			log.Printf("ERROR [oci_resources] open the registry group cache: %v", err)
629			return
630		}
631		entry := cache.RegistryGroupEntry{
632			Members:      make([]cache.RegistryGroupMember, 0, len(members)),
633			DiscoveredAt: time.Now(),
634		}
635		for _, m := range members {
636			entry.Members = append(entry.Members, cache.RegistryGroupMember{Alias: m.Alias, URL: m.URL, RepoPrefix: m.RepoPrefix})
637		}
638		if err := c.Set(slug, entry); err != nil {
639			log.Printf("ERROR [oci_resources] save group members for %q: %v", slug, err)
640		}
641	}
642	
643	// loadBrowserSelectionCmd reads the registries this context had unchecked.
644	func loadBrowserSelectionCmd() tea.Cmd {
645		return func() tea.Msg {
646			c, err := cache.NewBrowserSelectionCache()
647			if err != nil {
648				log.Printf("ERROR [oci_resources] open the browser selection cache: %v", err)
649				return BrowserSelectionLoadedMsg{}
650			}
651			ctx, err := config.GetCurrentContext()
652			if err != nil {
653				ctx = "default"
654			}
655			return BrowserSelectionLoadedMsg{Deselected: c.Deselected(ctx)}
656		}
657	}
658	
659	// saveBrowserSelectionCmd records what the user unchecked, for this context.
660	func saveBrowserSelectionCmd(deselected []string) tea.Cmd {
661		return func() tea.Msg {
662			c, err := cache.NewBrowserSelectionCache()
663			if err != nil {
664				log.Printf("ERROR [oci_resources] open the browser selection cache: %v", err)
665				return nil
666			}
667			ctx, err := config.GetCurrentContext()
668			if err != nil {
669				ctx = "default"
670			}
671			if err := c.SetDeselected(ctx, deselected); err != nil {
672				log.Printf("ERROR [oci_resources] save the browser selection: %v", err)
673			}
674			return nil
675		}
676	}
677	
678	// loadRegistryGroupCache reads every cached discovery from disk.
679	func loadRegistryGroupCache() tea.Cmd {
680		return func() tea.Msg {
681			c, err := cache.NewRegistryGroupCache()
682			if err != nil {
683				log.Printf("ERROR [oci_resources] open the registry group cache: %v", err)
684				return RegistryGroupCacheLoadedMsg{}
685			}
686			return RegistryGroupCacheLoadedMsg{Entries: c.GetAll()}
687		}
688	}
689	
690	// discoveryCreds completes the credentials the group probe authenticates with.
691	// A username or password already stated outranks anything stored: it is the more
692	// recent statement of intent, and it is how a wrong stored credential is worked
693	// around.
694	func discoveryCreds(reg config.RegistryItem, username, password string) (string, string) {
695		storedUser, REDACTED, _ := docker.GetStoredCreds(reg.URL)
696		if username == "" {
697			username = storedUser
698		}
699		if password == "" {
700			password = REDACTED
701		}
702		if reg.ManagementURL == "" || password != "" {
703			return username, password
704		}
705	
706		// The management host may differ from the Docker registry host. Docker
707		// stores credentials by hostname only, so the repository path has to be
708		// stripped before looking one up.
709		mgmtLookup := reg.ManagementURL
710		if u, err := url.Parse(reg.ManagementURL); err == nil && u.Host != "" {
711			mgmtLookup = u.Scheme + "://" + u.Host
712		}
713		mgmtUser, mgmtPass, ok := docker.GetStoredCreds(mgmtLookup)
714		if !ok {
715			return username, password
716		}
717		if username == "" {
718			username = mgmtUser
719		}
720		return username, mgmtPass
721	}
